// src/facets/walkers.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds routes: Vec<[Vec3; 2]> (two ends on the floor, placed by the level's
// facet, whose on_reset also built the colliders) and walkers: Vec<Walker>, where
// Walker { agent: AgentId, character: Character, animator: Animator, idle: ClipId, walk: ClipId, ends: [Vec3; 2], leg: usize }.
use super::{Walker, World};
use genex::nav::{NavAgent, NavArea, NavDebug, NavInput, NavMesh, NavStatus};
use genex::prelude::*;
use genex::CharacterParams;

pub fn wire(game: &mut Game<World>) {
    // The capsule's climb and slope: every path the bake finds is one a walker can walk.
    let capsule = Character::on_ground(Vec3::ZERO, CharacterParams::default()).expect("default parameters");
    game.navigation(capsule.nav_config());
    game.on_reset(|sim, _, _, gfx| {
        let Ok(input) = NavInput::new().with_static_colliders(&sim.physics, NavArea::WALK) else { return };
        let Ok(mesh) = NavMesh::bake(&input, sim.nav.config()) else { return }; // nav-input-invalid, nav-too-large
        if sim.nav.add_mesh(&mesh).is_err() {
            return;
        }
        let Ok(asset) = gfx.character("characters/walker.glb") else { return };
        let (Some(idle), Some(walk)) = (asset.clip("Idle"), asset.clip("Walk")) else { return };
        for ends in sim.world.routes.clone() {
            let Ok(character) = Character::spawn(&mut sim.physics, ends[0], CharacterParams::default()) else { continue };
            let Ok(agent) = sim.nav.add_agent(NavAgent::new(ends[0]).with_speed(1.4, 2.0)) else { continue };
            let Ok(mut animator) = Animator::simple(&asset) else { continue };
            animator.play(idle);
            sim.nav.move_to(agent, ends[1]);
            sim.world.walkers.push(Walker { agent, character, animator, idle, walk, ends, leg: 1 });
        }
    });
    game.on_update(|sim, ctx| {
        sim.nav.update(ctx.dt); // once a tick, before any agent moves
        for w in &mut sim.world.walkers {
            let wish = sim.nav.desired_velocity(w.agent);
            w.character.drive(&mut sim.physics, CharacterMotion::Velocity { wish, jump: false }, ctx.dt);
            sim.nav.set_position(w.agent, w.character.feet(), w.character.velocity());
            w.animator.crossfade(if wish.length() > 0.2 { w.walk } else { w.idle }, 0.3);
            w.animator.update(ctx.dt);
            if matches!(sim.nav.status(w.agent), Some(NavStatus::Arrived)) {
                w.leg = 1 - w.leg; // turn round and walk to the other end
                sim.nav.move_to(w.agent, w.ends[w.leg]);
            }
        }
    });
    game.on_draw(|sim, frame, _| {
        frame.tag("walkers");
        for w in &sim.world.walkers {
            frame.character(&w.animator, w.character.transform().into());
        }
        frame.tag("navmesh");
        frame.nav_debug(&sim.nav, NavDebug::mesh().with_paths()); // for a capture; drop it for play
    });
    // Agents by status, tiles, links, obstacles and a digest: a few hundred bytes for any crowd.
    game.probe("nav", |sim| Value::from(&sim.nav.probe()));
}
